const m = $json.body?.payload ?? {};
const BOTS = ['__NUMERO_DO_BOT__', '__BOT_LID__'];               // grupos com addressingMode 'lid' mencionam pelo LID
const GROUP = '__GROUP_ID__';

if (!m.id || m.fromMe) return [];

// privado = conversa 1:1 (@c.us ou @lid); outros grupos, status e canais são descartados
const privado = /@(c\.us|lid)$/.test(String(m.from));
if (!privado && m.from !== GROUP) return [];
if (privado && !m.body) return [];                               // mídia/sistema: ignora

// deduplica reentrega do webhook (só vale com o workflow ativo)
const s = $getWorkflowStaticData('global');
s.vistos ??= [];
if (s.vistos.includes(m.id)) return [];
s.vistos = [...s.vistos.slice(-200), m.id];

const k = m._data?.key ?? {};
if (!privado) {
  // NOWEB: mentionedIds vem null; as menções estão no contextInfo da mensagem crua
  const ctx = Object.values(m._data?.message ?? {}).find(x => x?.contextInfo)?.contextInfo;
  const ids = [...(m.mentionedIds ?? []), ...(ctx?.mentionedJid ?? [])].map(String);
  const marcado = BOTS.some(b => ids.some(x => x.includes(b)) || String(m.body).includes('@' + b));
  if (!marcado) return [];
}

// remetente: o campo que não for @lid (participantAlt/remoteJidAlt trazem o número quando o chat usa LID)
const cands = privado ? [k.remoteJidAlt, k.senderPn, m.from]
                      : [k.participantAlt, m.participant, k.participant, m.author];
const quem = cands.find(x => x && !String(x).endsWith('@lid'));
const num = String(quem ?? '').replace(/\D/g, '');
return [{ json: { num, privado, chatId: m.from } }];

// cabeçalhos e valores da planilha: 'Data de Referência' -> 'data_de_referência'
const norm = s => String(s ?? '').trim().toLowerCase().replace(/ /g, '_');
const rows = n => $(n).all().map(i => Object.fromEntries(Object.entries(i.json).map(([k, v]) => [norm(k), v])));
// data do Sheets: '26/09/2026' (formatada) ou serial numérico -> '2026-09-26'
const iso = v => typeof v === 'number' ? DateTime.fromISO('1899-12-30').plus({ days: v }).toISODate()
                                       : String(v ?? '').trim().split('/').reverse().join('-');
const preencher = (t, vars) => t.replace(/\{\{([^}]+)\}\}/g, (m, k) => vars[k.trim()] ?? m);
const msg = t => rows('Mensagens').find(m => norm(m.tipo) === t).mensagem;
const tr = rows('Trocas').filter(t => norm(t.status) === 'aprovada');
const efetivo = (nome, dia) => tr.find(t => t.pessoa_original === nome && iso(t['data_de_referência']) === dia)?.pessoa_substituta ?? nome;

const hora = v => typeof v === 'number' ? DateTime.fromISO('2000-01-01').plus({ minutes: Math.round(v * 1440) }).toFormat('HH:mm')
                                        : String(v ?? '').trim();

const { num, privado, chatId } = $('Code: filtrar').first().json;
const pessoa = rows('Pessoas').find(p => String(p.telefone).replace(/\D/g, '') === num);
if (!pessoa) return [];                                          // remetente desconhecido: silêncio

const hoje = $now.toISODate();
const prox = rows('Escalas')
  .map(e => { const dia = iso(e.data); return { dia, horario: hora(e['horário']), nome: efetivo(e.nome, dia) }; })
  .filter(e => e.nome === pessoa.nome && e.dia >= hoje)
  .sort((a, b) => a.dia.localeCompare(b.dia))[0];

const texto = preencher(msg(prox ? 'próxima' : 'sem_escala'), {
  pessoa: privado ? pessoa.nome : '@' + num,                       // privado: sem menção
  data: prox ? prox.dia.split('-').reverse().join('/') : '',
  horario: prox?.horario ?? '',
});
return [{ json: { texto, chatId, mentions: privado ? [] : [num + '@c.us'] } }];

